	EVENT_INFO_STORMARION_DESC = "Tower-Defense in Voidstorm an der Stormarion Citadel — beginnt alle 30 Minuten. Wehrt die Wellen zusammen mit allen in der Zone ab.",
	EVENT_INFO_STORMARION_REWARD = "Pro Durchlauf: Stormarion Core, Voidlight Marl, Gold und Veteranen-Ausrüstung. Die wöchentliche Truhe 'Stand Your Ground' hat eine Chance auf das Reittier Contained Stormarion Defender und ein Haustier, dazu Ruf bei The Singularity.",
	EVENT_INFO_HARANIR_DESC = "Ein ruhigeres Story-Ereignis in Harandar. Nimm die Wochenquest 'Lost Legends' an, wähle ein Relikt und spiele seine Lore-Questreihe (solo machbar).",
	EVENT_INFO_HARANIR_REWARD = "Eine Wochentruhe, Hara'ti-Ruf und ein Einrichtungsstück passend zu deinem Relikt. Sammle alle Relikt-Geschichten für den Titel 'Chronicler of the Haranir'.",
	EVENT_WEEKLY_DONE = "Wochenquest erledigt",
