	MODEL_PREVIEW_RESET = "Zurücksetzen",
	MODEL_PREVIEW_REWARDS_HINT = "Umschalt-Klick: Belohnungen ansehen",
	WORLD_SUBTITLE = "Mitternachts wöchentlicher Weltinhalt in Quel'Thalas. In einer Zone ist eine Ritualstätte aktiv, in einer anderen greift die Leere an — beide teilen den Basar-Hub, Feldauszeichnungen und Ansehen.",
	INFO_DRAWER_BODY_WORLD = "Void & Rituals vereint Mitternachts zwei wechselnde Weltsysteme. Ritualstätten: störe die aktive Stätte (violettes Kartensymbol) am Obelisken. Void-Angriffe: schließe Void-Schläge in der aktiven Zone ab, um einen Void-Einfall auszulösen. Beide geben Feldauszeichnungen, füllen deine Schatzkammer-Weltzeile und speisen das gemeinsame Ritualstätten-Ansehen. Beide Wochenquests gibt es am Basar-Hub in Silbermond.",
	TAB_REFERENCE = "Grundlagen",
