	PROFHUB_GOAL_TT_ALLROUND = "Die Konsens-Startroute: eine ausgewogene Reihenfolge für deine ersten Punkte — solide Craftkraft ohne Nischen-Festlegung.",
	PROFHUB_GOAL_TT_GOLD = "Bevorzugt Bäume, deren Produkte sich gut verkaufen (Verzauberungen, Fläschchen, Ballen-Cooldowns, geschliffene Steine). Wähle dies, wenn Gold dein Ziel ist.",
	PROFHUB_GOAL_TT_SELF = "Bevorzugt eigene Verbrauchsgüter und Ausrüstung sowie Material-Selbstversorgung gegenüber Marktwert.",
	PROFHUB_WEEKLY_TRAINER_REQ_ENCH = "(freigeschaltet über die Intro bei Captain Flaresworn — Arbeitsauftrag-Station; braucht zudem Skill 25)",
	PROFHUB_ACCESSORY_HINT_FMT = "Tipp: %d Zubehör-Slot(s) leer — Zubehör gibt Skill und Stats. Andere Handwerker stellen es her (AH-Kategorie: Berufsausrüstung).",
	INFO_DRAWER_BODY_CONSUMABLES = "Verbrauchsmaterialien für Midnight Season 1 pro Spezifikation (Wowhead-Liste). Nutze Mein Charakter, < > oder die Suche (z. B. Chaos, Biest), um eine Vorschau einer anderen Spezifikation anzuzeigen, ohne sich erneut anzumelden.",
	MACROS_MACRO_NAME_FMT = "%s",
	MACROS_COPY_SUFFIX = "Kopieren du den Text unten nach Esc > Makros > Neu. Ziehe dann das Makrosymbol an eine Stelle in deiner Aktionsleiste (z. B. 1, 2 oder E).",
	MACROS_INTERRUPT_SUBTITLE = "Mitternachtstipp: Stoppt einen gegnerischen Zauber mit einem Knopfdruck. Wähle oben eine Variante (Fokus oder Mouseover), lies die Notiz und kopiere dann den Text unten.",
	MACROS_INTERRUPT_VARIANT_FOCUS = "Fokus",
	MACROS_INTERRUPT_VARIANT_MOUSEOVER = "Mouseover",
	MACROS_INTERRUPT_DESC_FOCUS = "Unterbricht dein Fokusziel, wenn es ein lebender Gegner ist, sonst dein aktuelles Ziel. Setze den gefährlichen Zauberwirker einmal auf Fokus (/focus) und kämpfe normal weiter — dieses Makro ändert oder löscht deinen Fokus nie.",
	MACROS_INTERRUPT_DESC_MOUSEOVER = "Unterbricht den Gegner unter deinem Mauszeiger (funktioniert auch auf Namensplaketten und Frames), sonst dein aktuelles Ziel. Kein Fokus nötig: Zeiger auf den Zauberwirker und drücken.",
	MACROS_UTILITY_SUBTITLE = "Mitternachtstipp: Praktische Makros für deine Spezifikation (Cursor, Mouseover, Fokus). Wähle oben eine aus, lesen du die Notiz und kopieren du dann den Text unten.",
