	LAYOUT_PROTOTYPE_SUBTITLE = "Prototyp – vollständige US-Tastaturvorschau: Mitternachtstasten leuchten auf; andere ergrauten. Bewege den Mauszeiger oder klicke. Tipps auf der Registerkarte „Anleitung“ können hierher springen und einen Schlüssel hervorheben. Beim Austausch sicher zu entfernen.",
	LAYOUT_KEY_UNUSED_TOOLTIP = "|cff888888Wird nicht in der Midnight Hunter-Bindungskarte verwendet.|r",
	LAYOUT_KEY_MODIFIER_TOOLTIP = "|cff888888Modifikatortaste – WoW verarbeitet Umschalt-/Strg-/Alt-Kombinationen getrennt von dieser Zauberkarte.|r",
	LAYOUT_KEY_NAV_TOOLTIP = "|cff888888Navigations-/Bearbeitungscluster – nicht Teil der Midnight-Tastenkarte.|r",
