	LAYOUT_KEY_G_OPTIONAL_TOOLTIP = "|cffaaaaaaSlot G existiert im Raster, aber dieses Team lässt ihn oft leer – optional bind.|r",
	LAYOUT_KEY_ROLE_TOOLTIP_FMT = "|cffffcc00%s|r",
	LAYOUT_KEY_BIND_LAYER_FMT = "|cffe0e070%s|r — %s",
	LAYOUT_KEY_MOVEMENT_TOOLTIP = "Bewege Ihren Charakter: W nach vorne, S nach hinten, A/D nach hinten, Maus zum Drehen. WoW verwendet diese standardmäßig – halten du zum Gehen frei.",
	LAYOUT_KEY_TAB_TOOLTIP = "Mit der Tabulatortaste wechseln du die Ziele. WoW verwendet es standardmäßig – halten du Tab frei, damit du im Kampf schnell den richtigen Feind auswählen können.",
	LAYOUT_KEY_PREFERRED_TOOLTIP = "Mitternachtstipp: Halte diese Taste für Zaubersprüche, Makros oder Umschalt-/Strg-/Alt-Kombinationen frei – die gleiche Idee wie die leuchtenden F-Tasten auf Ihren Aktionsleisten.",
	LAYOUT_LEGEND = "|cff33ff61Green|r = bewegen (W A S D).\\n|cffe0e070Gold|r = Zauber und Abkürzungen auf dieser Karte.\\n|cff59d9ffTab|r = Ziele schnell wechseln.\\n|cff888888Grey|r = nicht auf dieser Starterkarte.",
	LAYOUT_KEY_HIGHLIGHT_FROM_GUIDE = "|cffe0e070Geöffnet von Ihrem Level-Guide – dieser Schlüssel befindet sich auf der Mitternachtskarte.|r",
	MODULE_PLACEHOLDER = "Modulplatzhalter – Inhalt für „%s“ wird hier bereitgestellt.",
	INFO_DRAWER_TOGGLE_SHOW = "Info",
	INFO_DRAWER_TOGGLE_HIDE = "Schließen",
	INFO_DRAWER_TITLE_FMT = "%s – Verwendung",
	INFO_DRAWER_BODY_DELVES = "Midnight-Tiefen-Kommandozentrale für deinen aktuellen Charakter.\\n\\nErweitere Great Vault für die wöchentliche Belohnungsverfolgung oder Midnight-Tiefen für Saisonwährungen (wiederhergestellte Kofferschlüssel, wöchentliche Splitter, Untermünzen), Reise des Tiefenforschers/Ruf und die vollständige Liste der Höhlen mit Live-Erkennung von Reichtümern aus Karten-POIs.\\n\\nNavigation: Klicke mit der rechten Maustaste auf eine Zeile, um zum Eingang zu gelangen. |cffffcc00TomTom (empfohlen)|r fügt den Kartenpfeil und die Wegpunktwarteschlange hinzu. |cff00ff00Reiseassistent|r (Popup, wenn du weit weg sind) zeigt Hearthstone- und Hub-Portal-Verknüpfungen an und funktioniert |cffffff00ohne|r TomTom.\\n\\nFind Nearest Bountiful erfordert die Installation von TomTom.",
	INFO_DRAWER_BODY_ACCOUNT = "Von diesem Add-on lokal gespeicherte charakterübergreifende Liste (gespeicherte Variablen auf Ihrem PC – keine Blizzard-Cloud-Synchronisierung).\\n\\nJede Zeile listet Schlüssel, Scherben, Untermünzen, Berufsecho und eine kompakte Great Vault-Zusammenfassung mit umfangreichen Tooltips auf; dein angemeldeter Charakter wird hervorgehoben und die Sortierung begünstigt die Nützlichkeit.\\n\\nZeilen werden bei Anmeldung und Währung/wöchentlichen Ereignissen aktualisiert. Beim Löschen werden nur Add-on-Snapshot-Daten entfernt – niemals dein tatsächlicher WoW-Charakter.",
	INFO_DRAWER_BODY_RARES = "Mitternachts-Weltrares nach Zone (Eversong, Zul'Aman, Harandar, Voidstorm).\\n\\nWähle links eine Zone. Grün = auf diesem Charakter erledigt; grünes UP = Vignette am Spawn (wahrscheinlich aktiv); grauer Strich = gerade nicht auf deiner Karte.\\n\\nNächster Rare = ein Pin; Route generieren = alle offenen Rares in TomTom. UP-Status ist ungefähr – Zonekarte öffnen oder näher heran, wenn es unsicher wirkt.",
	RARES_TITLE = "Mitternachts-Rares",
	RARES_SUBTITLE_FMT = "%d/%d erledigt · %d jetzt auf Karte sichtbar (silberner Stern)",
	RARES_EMPTY_ZONE = "Keine Rare-Liste für diese Zone.",
	RARES_BTN_NEAREST = "Nächsten Rare finden",
	RARES_BTN_ROUTE = "Route generieren",
	RARES_NEAREST_ROUTE = "|cffffff78Midnight Helper:|r TomTom: nächster Rare — %s",
	RARES_NEAREST_NONE = "Keine offenen Rares mehr in dieser Zone.",
	RARES_NEAREST_NO_TRAVEL = "Reiseassistent nicht verfügbar (Tiefen-Modul nicht geladen).",
	RARES_ROUTE_DONE_FMT = "%d/%d offene Rares in TomTom eingereiht. %s",
	RARES_ROUTE_ORDER_NEAR = "Reihenfolge: nächster zuerst, dann jeweils der nächste.",
	RARES_ROUTE_ORDER_LIST = "Reihenfolge: Listenreihenfolge (Position unbekannt).",
	RARES_TAG_UP = "UP",
	RARES_TAG_DOWN = "—",
	RARES_TIP_DONE = "Diese Woche auf diesem Charakter erledigt (Reset Mittwoch).",
	RARES_TIP_UP = "Wahrscheinlich aktiv (Kartenvignette am Spawn).",
	RARES_TIP_DOWN = "Gerade nicht auf der Karte — kann später spawnen.",
	RARES_TIP_VIGNETTE_NOTE = "Kartenstatus ist ungefähr; Zonekarte öffnen oder näher heran bei Unsicherheit.",
	INFO_DRAWER_BODY_SMC = "Silvermoon City-Referenz für Mitternacht (Karte 2393). Die gleiche Schriftrolle beginnt mit der Wöchentlich-/Hub-Checkliste, wenn Quest-IDs konfiguriert sind, und setzt sich dann in kategorisierten Pin-Rastern fort – Wesentliche Dienste, Reisen, Quest-Hubs, Berufstrainer, Sammeln und mehr.\\n\\nJede Standortschaltfläche legt den Benutzerwegpunkt von Blizzard fest und spiegelt ihn bei installiertem TomTom durch den Schrägstrich-Helfer (/way #2393 …) wider.\\n\\nDer Fortschritt der Checkliste färbt zugehörige Wegpunktschaltflächen grün; Aktualisiere die Quest-IDs in den Daten nach größeren Patches, wenn eine Zeile falsch aussieht.",
	INFO_DRAWER_BODY_PROFESSIONS = "Verfolgt die Mitternachtsberufs-Wissenspunkte (KP) für deinen aktuellen Charakter sowie Währungslinien, wenn der Kunde du preisgibt (Unlegierter Überfluss, Artisan's Moxie, wöchentliche Splitter von Dundun).\\n\\nDarunter werden in zwei Spalten Wissenssammelquests und Berufsbücher pro Handel aufgeführt – Symbole zeigen an, ob jede Quest abgeschlossen ist. Klicke auf eine Zeile, um nur diesen Pin an TomTom zu senden (löscht andere Wegpunkte; Travel Assistant verarbeitet zonenübergreifende Sprünge, wenn TomTom geladen ist).\\n\\nUntere Schaltflächen stellen unvollständige Pins in die Stapelwarteschlange: Schätze generieren oder Bücher generieren (das nächste Unvollendete zuerst, wenn deine Kartenposition verfügbar ist).",
	INFO_DRAWER_BODY_GUIDE = "Spezifikationsspezifische Level-Referenzen im Stil von Icy Veins: Statuspriorität, Ausrüstungsauswahl, Verbrauchsmaterialien, die entsprechend dem gefiltert sind, was dein Level tatsächlich verwenden kann, optionale Zaubertippreihen und der Level-Ratgeber mit Klammerregisterkarten für Rotation, Verteidigung und Talentfokus.\\n\\nWenn deine Klasse über eine Midnight-Tastenkarte verfügt (vorerst Jäger/Paladin), können Tipps eine goldene Schlüsselschaltfläche anzeigen – klicke darauf, um die Registerkarte „Layout“ zu öffnen und diese Taste auf der Tastatur hervorzuheben. Dadurch wird das Lesen (was gedrückt werden muss) mit der Platzierung (wo auf der Tastatur) verknüpft, sodass du „learning by doing“ lernen.\\n\\nDie globale Suchleiste versteht Leitfäden-Schlüsselwörter und kann zwischen den Midnight Helper-Registerkarten wechseln; Mit der Vorschau können du eine andere Spezialisierung lesen, ohne sich erneut anzumelden, während „Mein Charakter“ zu deiner aktiven Spezialisierung zurückkehrt.\\n\\nDie Sichtbarkeit der Registerkarte „Anleitung“ folgt den Einstellungen: „Auto“ (wird bei Stufe 90+ ausgeblendet), „Immer anzeigen“ oder „Immer ausblenden“.",
	INFO_DRAWER_BODY_MACROS = "Registerkarte „Unterbrechen“: Team-Kick-Makro (Fokus zuerst). Registerkarte „Dienstprogramm“: Zusätzliche Spezifikationsmakros (Cursor-Bodenzauber, Mouseover-Heilungen und ähnliches) aus dem Teampaket. Wähle eine Zeile aus, lesen du den Tipp, kopieren du den Text.\\n\\nDaten können sich nach Patches ändern – melden du fehlende Zauber dem Team.",
	INFO_DRAWER_BODY_ADDONS = "Hub für optionale Tools, die in Midnight Helper gebündelt sind, anstatt separate Downloads.\\n\\nWähle oben eine Unterregisterkarte aus – heute ist das Platynator: Wago-Link, Profil-String-Import und die visuelle Galerie von MF Platynator.\\n\\nZusätzliche Partnerpanels werden hier automatisch registriert, wenn zukünftige Module ausgeliefert werden.",
	ABOUT_WINDOW_TITLE = "Über Midnight Helper",
	ABOUT_VERSION_FMT = "Installierte Version: |cffffcc00%s|r",
	ABOUT_WINDOW_BODY =
	"Autoren: Inchy & Gemma & Cursor"
		.. ""
		.. "Alles-in-einem-Midnight-Nachschlag: Delves & Vault, Tiefen-Coach & Gruppenteilen, Delve-Items-Popup, Account-Snapshot, SMC City Guide, Berufe (KP + Schätze), Leveling Guides, gebündelte Tools — EN / NL / DE / FR / ES / PT / IT.",
	MAIN_TITLE_VERSION_FMT = "v%s",
	BROKER_TOOLTIP_VERSION_FMT = "Version: %s",
	CHANGELOG_TITLE = "Mitternachtshelfer-Änderungsprotokoll",
	CHANGELOG_SUBTITLE = "Version %s",
	CHANGELOG_VERSION_FMT = "Version %s",
	CHANGELOG_CLOSE = "Schließen",
	CHANGELOG_CB_UNTIL_NEXT = "Erst in der nächsten Version wieder anzeigen",
	CHANGELOG_CB_NEVER = "Änderungsprotokoll dauerhaft ausblenden",
	CHANGELOG_120_1 = "Kompaktes Leveling Advisor-Panel mit Klammern und Registerkarten pro Level hinzugefügt (Rotation/Defensiv/Talentfokus).",
	CHANGELOG_120_2 = "Verbesserter Abschnitt „Verbrauchsmaterialien“: Zeigt nur verwendbare Gegenstände auf Ihrem aktuellen Level an und erklärt die nächsten Freischaltungen.",
	CHANGELOG_120_3 = "Konto-Snapshot-Zeilenverwaltung hinzugefügt: Veraltete Zeichen sicher löschen (mit Bestätigung) plus Zebrastreifen.",
	CHANGELOG_120_4 = "Verbesserte Lokalisierungskonsistenz (EN/NL) und hinzugefügtes In-Guide-Statistik-Glossar über das neue ? Statistik-Schaltfläche.",
	CHANGELOG_121_1 = "Hauptfenster: Die inneren Panels respektieren den goldenen Dialograhmen – Eckverzierungen bleiben sichtbar und der untere/rechte „leere Rand“ neben dem Größenänderungsgriff ist verschwunden.",
	CHANGELOG_121_2 = "„Info“ und „Info“ verwenden wieder die Standardschaltflächen des Blizzard-Bedienfelds (gleiche Behandlung wie „Suche“/ „Mein Charakter“), um auf allen Clients ein einheitliches Erscheinungsbild zu gewährleisten.",
	CHANGELOG_121_3 = "Nur geringfügige Politur; Delves, Vault, Guides und Lokalisierungsverhalten unverändert – sicheres Drop-In-Update.",
	CHANGELOG_122_1 = "Registerkarte „Makros“: Ein-Klick-Team-Interrupt-Makro sowie kuratierte Hilfsmakros pro Spezifikation (Cursor, Mouseover, Fokus) – Kopieren, Einfügen, Abspielen.",
	CHANGELOG_122_2 = "Sieh dir jede Spezifikation in der Vorschau an, ohne sich erneut anzumelden: Die Leitfadensuche aktualisiert Nivellierungstipps, Tastaturlayout und Makros für diese Klasse/Spezifikation auf einmal.",
	CHANGELOG_122_3 = "Guide-Suche und Chat-Nachrichten folgen deiner Sprachauswahl (/mh lang en oder nl).",
	CHANGELOG_122_4 = "Aktualisierung des Tastenlayouts um Mitternacht: Unterbrechung auf E, klarere Rollenplätze, intelligenterer Überlauf (Alt, Umschalt, Strg).",
	CHANGELOG_122_5 = "Es wird immer noch gekocht: Alles in Midnight Helper kann sich ändern und ständig verbessert werden – es werden weiterhin Patches verfügbar sein. Feedback willkommen!",
	CHANGELOG_130_1 = "Tiefen-Gruppenteilen: Sende Tiefentipps an Gruppen, Raids oder Instanzen vom Tiefen-Coach (Brief, Boss, Abschnitte, Kopie). Testen (/say), wenn du alleine sind.",
	CHANGELOG_130_2 = "Popup-Fenster für Gewölbegegenstände: RAID-R Mini und Trovehunter's Bounty in Gewölben – automatische Anzeige + Minikartensymbole (nur im Gewölbe; links = Popup, rechts = verwenden).",
	CHANGELOG_130_3 = "Tiefen-Coach: Umschalt + Mausrad skaliert das gesamte Panel (wie Midnight Helper). Ziehe die Ecke, den unteren oder rechten Rand, um die Größe zu ändern. Tipps zum Scrollen mit dem Rad.",
	CHANGELOG_130_4 = "Boss-Spotlight: Zuverlässige Vorschau beim ersten Laden, Textkorrektur beim Laden und gespeicherter Zoom pro Boss.",
	CHANGELOG_130_5 = "Korrekturen: Gruppenfreigabe nur, wenn du wirklich in einer Gruppe sind; weniger Chatfehler; Rechtschreiblinks in geteilten Tipps (EN/NL).",
	CHANGELOG_130_6 = "Von hier aus können kleine Patch-Releases den Valeera-Codenamen in Notizen verwenden – wichtige Funktionen bleiben auf 1.x.",
	CHANGELOG_126_1 = "Tiefen-Coach: schwebende Tipps für alle 11 Mitternachtstauchgänge (Übersicht, Route, Müll, Boss) auf Englisch und Niederländisch.",
	CHANGELOG_126_2 = "Boss-Spotlight mit 3D-Vorschau; Scrolle über das Modell, um hinein-/herauszuzoomen (pro Boss gespeichert).",
	CHANGELOG_126_3 = "Blaue Zauberlinks in Tipps; Vorschau über die Registerkarte „Delves“ oder /mh coach; Auto-Show in Delve.",
	CHANGELOG_126_4 = "Verschiebbares und in der Größe veränderbares Coach-Fenster mit Minimierung.",
	CHANGELOG_126_5 = "Boss-Kamera- und Tooltip-Korrekturen für den Einzelhandel.",
	CHANGELOG_125_1 = "Neue Registerkarte „Rollenakademie“: Tank- und Heilpfade mit Vorbereitungschecklisten, Triage-Tipps und einem sanften Aufstieg von Höhlen zu Dungeons.",
	CHANGELOG_125_2 = "Schnelle Links von der Role Academy zu Makros, Verbrauchsmaterialien, Level-Anleitungen und Höhlen.",
	CHANGELOG_125_3 = "Suche nach Schlüsselwörtern (Tank, Heilen, Akademie, Mentor), um die Rollenakademie zu öffnen.",
	CHANGELOG_124_1 = "Delve- und Berufsrouting: Wegpunkt-Fallback der Blizzard-Karte, wenn TomTom nicht installiert ist (SuperTrack + Reise-Popup unverändert).",
	CHANGELOG_124_2 = "Kontoübersicht: Wöchentliche Berufswährungen im Tooltip (Überfluss, Dundun-Scherben, Moxie-Zusammenfassung).",
	CHANGELOG_124_3 = "Tolle Erinnerungen zum Zurücksetzen des Tresors: Chat beim Anmelden, Minikarten-Tooltip-Zeilen und pulsierendes Minikartensymbol (konfigurierbar).",
	CHANGELOG_124_4 = "Politur des Account-Snapshots: Sortieren/Filtern, Level/ILVL, veraltetes Abzeichen, Unbefleckte Manakristalle; Suchrouting für Verbrauchsmaterialien.",
	CHANGELOG_123_1 = "Problem behoben, bei dem der Reiseassistent fälschlicherweise Hearthstone vorschlug, wenn man sich bereits in der Nähe einer Höhle oder in einer solchen befand.",
	CHANGELOG_123_2 = "Ein Lua-Fehler beim Routing zu reichhaltigen Höhlen (Kartenpositions-API) wurde behoben.",
	CHANGELOG_123_3 = "Registerkarte „Verbrauchsmaterialien“ in der Seitenleiste: Von Wowhead unterstützte Listen pro Spezifikation, mit Vorschau der Leitfadensuche.",
	CHANGELOG_123_4 = "Klarere TomTom-Navigation (EN/NL): optional für Kartenpfeile; Travel Assistant funktioniert ohne TomTom.",
